package com.vaijunto.repository;
import com.vaijunto.domain.entities.UserBlock; import org.springframework.data.jpa.repository.*; import java.util.*;
public interface UserBlockRepository extends JpaRepository<UserBlock, UUID> { boolean existsByUserLowIdAndUserHighId(UUID low, UUID high); Optional<UserBlock> findByUserLowIdAndUserHighId(UUID low, UUID high); @Query("select case when count(b)>0 then true else false end from UserBlock b where (b.userLow.id=:a and b.userHigh.id=:b) or (b.userLow.id=:b and b.userHigh.id=:a)") boolean existsBetween(@org.springframework.data.repository.query.Param("a") UUID a,@org.springframework.data.repository.query.Param("b") UUID b); @Query("select b from UserBlock b where b.userLow.id=:id or b.userHigh.id=:id") List<UserBlock> findForUser(@org.springframework.data.repository.query.Param("id") UUID id); }
